import 'package:firebase_core/firebase_core.dart';
import 'package:flutter/foundation.dart';

/// Initializes Firebase without coupling the rest of the application to it.
///
/// Native builds may use the standard Firebase platform files generated by
/// `flutterfire configure`. All platforms can alternatively use the
/// FIREBASE_* dart defines below.
class FirebaseConfig {
  static const _apiKey = String.fromEnvironment('FIREBASE_API_KEY');
  static const _appId = String.fromEnvironment('FIREBASE_APP_ID');
  static const _messagingSenderId =
      String.fromEnvironment('FIREBASE_MESSAGING_SENDER_ID');
  static const _projectId = String.fromEnvironment('FIREBASE_PROJECT_ID');
  static const _authDomain = String.fromEnvironment('FIREBASE_AUTH_DOMAIN');
  static const _storageBucket =
      String.fromEnvironment('FIREBASE_STORAGE_BUCKET');

  static bool get _hasExplicitOptions =>
      _apiKey.isNotEmpty &&
      _appId.isNotEmpty &&
      _messagingSenderId.isNotEmpty &&
      _projectId.isNotEmpty;

  static Future<bool> initialize() async {
    if (Firebase.apps.isNotEmpty) return true;

    try {
      if (_hasExplicitOptions) {
        await Firebase.initializeApp(
          options: FirebaseOptions(
            apiKey: _apiKey,
            appId: _appId,
            messagingSenderId: _messagingSenderId,
            projectId: _projectId,
            authDomain: _authDomain.isEmpty ? null : _authDomain,
            storageBucket: _storageBucket.isEmpty ? null : _storageBucket,
          ),
        );
      } else {
        // Uses google-services.json / GoogleService-Info.plist when present.
        await Firebase.initializeApp();
      }
      return true;
    } catch (error) {
      // Firebase is optional for every feature except phone OTP. Keeping the
      // failure isolated preserves password, Google, and cached-session login.
      debugPrint('[FIREBASE] Phone OTP is not configured: $error');
      return false;
    }
  }
}
